lib = '''def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def cells_of(grid, color):
    """All positions (i, j) holding the given color."""
    return [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color]

def bounding_box(positions):
    """(top, left, bottom, right) of the given cell positions."""
    return (min(i for i, _ in positions), min(j for _, j in positions),
            max(i for i, _ in positions), max(j for _, j in positions))

def crop(grid, top, left, height, width):
    """The height x width subgrid whose top-left cell is (top, left)."""
    return [row[left:left + width] for row in grid[top:top + height]]

def stamp(grid, pattern, top, left, keep_zero=False):
    """Copy pattern onto grid at (top, left); skip cells equal to 0 unless keep_zero."""
    for i, prow in enumerate(pattern):
        for j, v in enumerate(prow):
            if keep_zero or v != 0:
                if 0 <= top + i < len(grid) and 0 <= left + j < len(grid[0]):
                    grid[top + i][left + j] = v
    return grid

def stamp_pattern_at_seeds(grid, seed_color):
    """Replace each pixel of seed_color with the grid's other-color pattern, centered on the pixel."""
    bg = background(grid)
    other = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v not in (bg, seed_color)]
    t, l, b, r = bounding_box(other)
    pattern = crop(grid, t, l, b - t + 1, r - l + 1)
    out = [row[:] for row in grid]
    for i, j in cells_of(grid, seed_color):
        for a in range(-len(pattern) // 2 + 1, len(pattern) - len(pattern) // 2):
            for bb in range(-len(pattern[0]) // 2 + 1, len(pattern[0]) - len(pattern[0]) // 2):
                pi = len(pattern) // 2 + a
                pj = len(pattern[0]) // 2 + bb
                out[i + a][j + bb] = pattern[pi][pj]
    return out
'''
